import{_ as t,a as i,b as e,c as r,d as l,e as n}from"./chunks/image-20261116063213734.DKm6XmDP.js";import{_ as o,o as s,c as p,a2 as c}from"./chunks/framework.CmPiTyN0.js";const w=JSON.parse('{"title":"Tactical Map","description":"","frontmatter":{"title":"Tactical Map","outline":"deep"},"headers":[],"relativePath":"en/wiki/tactical-map.md","filePath":"en/wiki/tactical-map.md","lastUpdated":1794811249000}'),d={name:"en/wiki/tactical-map.md"};function g(m,a,h,u,_,f){return s(),p("div",null,[...a[0]||(a[0]=[c('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_9-tactical-map" tabindex="-1">9. Tactical Map <a class="header-anchor" href="#_9-tactical-map" aria-label="Permalink to &quot;9. Tactical Map&quot;">​</a></h2><p>The tactical map shows terrain, players, vehicles, missiles, and GPS target points, and supports zooming, dragging, following, and quick marking. Right-click a target to bind it as a GPS target or fill its position into the GPS panel.</p><h3 id="_9-1-gps-guided-weapon-integration" tabindex="-1">9.1 GPS-Guided Weapon Integration <a class="header-anchor" href="#_9-1-gps-guided-weapon-integration" aria-label="Permalink to &quot;9.1 GPS-Guided Weapon Integration&quot;">​</a></h3><ul><li>Select a target point on the tactical map and designate it as a GPS target.</li><li>Supports single-point and multi-point marking.</li><li>Multi-point mode manages multiple target points; radar mode selects targets from the radar panel.</li></ul><p><img src="'+t+'" alt="image-20261116062223016"></p><p><img src="'+i+'" alt="image-20261116062328942"></p><p><strong>Figures 9.1/9.2 Tactical map integrated with GPS-guided weapons.</strong></p><h3 id="_9-2-radar-target-list-integration" tabindex="-1">9.2 Radar Target List Integration <a class="header-anchor" href="#_9-2-radar-target-list-integration" aria-label="Permalink to &quot;9.2 Radar Target List Integration&quot;">​</a></h3><ul><li>The tactical map can open the radar target list, showing distance, altitude, speed, NCTR identification, IFF, and lock state.</li><li>Targets can be locked, and the current missile can be quick-fired if it meets the lock conditions.</li><li>The radar target list can hide friendly targets.</li></ul><p><img src="'+e+'" alt="image-20261116062648996"></p><p><img src="'+r+'" alt="image-20261116062852461"></p><p><strong>Figures 9.3/9.4 Tactical map integrated with the radar panel.</strong></p><h3 id="_9-3-artillery-map-and-mini-artillery-map" tabindex="-1">9.3 Artillery Map and Mini Artillery Map <a class="header-anchor" href="#_9-3-artillery-map-and-mini-artillery-map" aria-label="Permalink to &quot;9.3 Artillery Map and Mini Artillery Map&quot;">​</a></h3><ul><li><strong>Artillery map</strong>: after selecting a target, calculates elevation and impact distance with high/low ballistic solutions; left-click to fire; intended for RVP artillery weapons.</li><li><strong>Mini artillery map</strong>: shows a compact map in the screen corner when an artillery weapon is selected, computing the impact point from the current muzzle direction and elevation; left-click fires along the normal firing path. Accuracy is lower, so it is only for emergencies.</li></ul><p><img src="'+l+'" alt="image-20261116063139342"></p><p><img src="'+n+'" alt="image-20261116063213734"></p><p><strong>Figures 9.5/9.6 Artillery map.</strong></p><hr>',19)])])}const y=o(d,[["render",g]]);export{w as __pageData,y as default};
